def is_palindrome(s):
    return s == s[::-1]

def palindrome_pairs_brute(words):
    result = []
    n = len(words)
    for i in range(n):
        for j in range(n):
            if i != j and is_palindrome(words[i] + words[j]):    # check every ordered pair directly
                result.append([i, j])
    return result

