class TrieNode:
    def __init__(self):
        self.children = {}
        self.index = -1
        self.palin_suffix_indices = []       # indices whose REMAINING prefix (start..i) is a palindrome

def is_pal_range(s, i, j):
    while i < j:
        if s[i] != s[j]:
            return False
        i += 1; j -= 1
    return True

def palindrome_pairs(words):
    root = TrieNode()
    for idx, word in enumerate(words):
        node = root
        for i in range(len(word) - 1, -1, -1):                 # insert REVERSED
            if is_pal_range(word, 0, i):
                node.palin_suffix_indices.append(idx)
            c = word[i]
            node = node.children.setdefault(c, TrieNode())
        node.index = idx
        node.palin_suffix_indices.append(idx)                    # empty remaining prefix is trivially a palindrome

    result = []
    for idx, word in enumerate(words):
        node = root
        broke = False
        for i in range(len(word)):
            if node.index >= 0 and node.index != idx and is_pal_range(word, i, len(word) - 1):
                result.append([idx, node.index])                    # matched an ending word, remainder is palindrome
            c = word[i]
            if c not in node.children:
                broke = True
                break
            node = node.children[c]
        if not broke:
            for j in node.palin_suffix_indices:
                if j != idx:
                    result.append([idx, j])                            # symmetric case via stored indices
    return result

